function load(){api.scanner.get().success(function(n){$("#window_seconds").val(n.window_seconds),$("#min_chrome").val(n.min_chrome),$("#min_firefox").val(n.min_firefox),$("#min_safari").val(n.min_safari),$("#user_agents").val(n.user_agents||"")}).error(function(){errorFlash("Error fetching scanner settings")})}function save(){var n={window_seconds:parseInt($("#window_seconds").val(),10)||0,min_chrome:parseInt($("#min_chrome").val(),10)||0,min_firefox:parseInt($("#min_firefox").val(),10)||0,min_safari:parseInt($("#min_safari").val(),10)||0,user_agents:$("#user_agents").val()};api.scanner.put(n).success(function(){successFlash("Scanner settings saved")}).error(function(s){errorFlash(s.responseJSON&&s.responseJSON.message||"Error saving scanner settings")})}$(document).ready(function(){load()});
